"""Check the HTML generated by the GitHub Pages Jekyll engine."""
from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urlsplit, unquote
import json
import xml.etree.ElementTree as ET

ROOT = Path("_site")
BASE = "https://abnersolo.github.io"
URLS = ("/", "/math/group-ring-field-quotient-ideal/", "/lattice/gaussian-smoothing-parameter/")


class Page(HTMLParser):
    def __init__(self, path):
        super().__init__()
        self.ids, self.links, self.canonical = set(), [], []
        self.meta, self.math_count, self.h1_count = {}, 0, 0
        self.in_json, self.json_text, self.structured = False, "", []
        self.feed(path.read_text(encoding="utf-8"))

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if a.get("id"):
            self.ids.add(a["id"])
        if tag == "a" and a.get("href"):
            self.links.append(a["href"])
        if tag == "meta":
            self.meta[a.get("name", a.get("property", ""))] = a.get("content", "")
        if tag == "link" and a.get("rel") == "canonical":
            self.canonical.append(a["href"])
        if tag == "script" and a.get("type", "").startswith("math/tex"):
            self.math_count += 1
        if tag == "script" and a.get("type") == "application/ld+json":
            self.in_json, self.json_text = True, ""
        if tag == "h1":
            self.h1_count += 1

    def handle_data(self, data):
        if self.in_json:
            self.json_text += data

    def handle_endtag(self, tag):
        if tag == "script" and self.in_json:
            self.structured.append(json.loads(self.json_text))
            self.in_json = False


for url in URLS:
    page = Page(ROOT / url.strip("/") / "index.html")
    assert page.canonical == [BASE + url], (url, page.canonical)
    assert page.meta.get("description") and page.meta.get("robots") == "index,follow", url
    assert page.h1_count == 1 and page.structured, url
    if url != "/":
        assert page.math_count > 100, (url, page.math_count)
        assert any(item.get("@type") == "Article" for item in page.structured), url
    for href in page.links:
        target = urlsplit(href)
        if target.netloc and target.netloc != "abnersolo.github.io":
            continue
        p = ROOT / unquote(target.path or url).lstrip("/")
        if p.is_dir():
            p /= "index.html"
        assert p.is_file(), (url, href)
        if target.fragment:
            assert target.fragment in Page(p).ids, (url, href)
    print("PASS", BASE + url, "math:", page.math_count)

ns = {"s": "http://www.sitemaps.org/schemas/sitemap/0.9"}
locs = {n.text for n in ET.parse(ROOT / "sitemap.xml").findall("s:url/s:loc", ns)}
assert {BASE + url for url in URLS} <= locs, locs
assert not any("/notes/" in url or url.endswith("/404.html") for url in locs), locs
robots = (ROOT / "robots.txt").read_text(encoding="utf-8")
assert "Allow: /" in robots and "Sitemap: " + BASE + "/sitemap.xml" in robots
assert "Disallow:" not in robots and "{{" not in robots
assert Page(ROOT / "404.html").meta["robots"] == "noindex,follow"
print("PASS sitemap, robots, navigation, canonical, article metadata")
